class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1) 
        dp[0] = 0

        for i in range(n + 1):
            for word in dictionary:
                j = i - len(word)
                if j >= 0 and s[j:j+len(word)] == word:
                    dp[i] = min(dp[i], dp[j])

        return n - dp[n] - n
